<?php
declare(strict_types=1);
namespace Sentinel\Services;
use Sentinel\Core\{Database,RuntimeContext,HttpException};
final class FleetOperationsService
{
    use TenantOperations;
    public function __construct(private readonly Database $db,private readonly RuntimeContext $context,private readonly AuditService $audit,private readonly SiteAccessService $access) {}
    private function vehicle(string $id):array {$v=$this->row('fleet_vehicles','fleet_id',$id);$this->access->requireSite($v['site_id']);return $v;}
    private function due(array $v):bool {return (int)$v['odometer_km']>=(int)$v['next_service_km']||$v['next_service_on']<=gmdate('Y-m-d');}
    public function list(array $input,bool $self=false):array {$this->fields($input,$self?[]:['site_id']);if(!$self)$site=$this->access->requireSite($input['site_id']??null);$rows=$this->db->fetchAll('SELECT v.* FROM fleet_vehicles v WHERE v.company_id=:company'.($self?' AND EXISTS(SELECT 1 FROM fleet_trips t WHERE t.company_id=v.company_id AND t.fleet_id=v.fleet_id AND t.employee_id=:employee)':' AND v.site_id=:site').' ORDER BY v.fleet_id DESC LIMIT 200',$self?['company'=>$this->company(),'employee'=>$this->employee()]:['company'=>$this->company(),'site'=>$site['site_id']]);foreach($rows as&$v){$v['service_due']=$this->due($v);$p=['company'=>$this->company(),'fleet'=>$v['fleet_id']];$v['trips']=$this->db->fetchAll('SELECT * FROM fleet_trips WHERE company_id=:company AND fleet_id=:fleet'.($self?' AND employee_id=:employee':'').' ORDER BY trip_id DESC LIMIT 100',$self?$p+['employee'=>$this->employee()]:$p);if(!$self){$v['fuel']=$this->db->fetchAll('SELECT * FROM fleet_fuel WHERE company_id=:company AND fleet_id=:fleet ORDER BY fuel_id DESC LIMIT 100',$p);$v['services']=$this->db->fetchAll('SELECT * FROM fleet_services WHERE company_id=:company AND fleet_id=:fleet ORDER BY service_id DESC LIMIT 100',$p);}}unset($v);return array_values(array_filter($rows,fn($v)=>$this->access->allowed($v['site_id'])));}
    public function create(array $input):array {return $this->atomic(function()use($input){$this->fields($input,['site_id','registration','description','odometer_km','next_service_km','next_service_on']);$site=$this->access->requireSite($input['site_id']??null);$odo=$this->number($input['odometer_km']??null,0,10000000);$next=$this->number($input['next_service_km']??null,$odo+1,10000001);$reg=strtoupper($this->text($input['registration']??null,30));if($this->db->fetch('SELECT fleet_id FROM fleet_vehicles WHERE company_id=:company AND registration=:reg',['company'=>$this->company(),'reg'=>$reg]))throw HttpException::conflict('Fleet registration already exists.');$this->db->execute('INSERT INTO fleet_vehicles(company_id,site_id,registration,description,odometer_km,next_service_km,next_service_on) VALUES(:company,:site,:reg,:description,:odo,:next,:date)',['company'=>$this->company(),'site'=>$site['site_id'],'reg'=>$reg,'description'=>$this->text($input['description']??null,150),'odo'=>$odo,'next'=>$next,'date'=>$this->day($input['next_service_on']??null)]);return $this->created('fleet_vehicle');});}
    public function allocate(string $id,array $input):array {return $this->atomic(function()use($id,$input){$this->fields($input,['employee_id','starts_at','ends_at','purpose']);$v=$this->vehicle($id);$e=$this->row('employees','employee_id',$input['employee_id']??null);$start=$this->at($input['starts_at']??null);$end=$this->at($input['ends_at']??null);if($v['state']!=='ACTIVE'||$this->due($v)||$e['employment_status']!=='ACTIVE'||$end<=$start||$end<=gmdate('Y-m-d H:i:s')||strtotime($end.' UTC')-strtotime($start.' UTC')>48*3600)throw HttpException::conflict('Choose an available serviced vehicle, active driver and valid trip of up to 48 hours.');if($this->db->fetch("SELECT trip_id FROM fleet_trips WHERE company_id=:company AND (fleet_id=:fleet OR employee_id=:employee) AND state IN ('ALLOCATED','IN_PROGRESS') AND starts_at<:end AND ends_at>:start",['company'=>$this->company(),'fleet'=>$id,'employee'=>$e['employee_id'],'start'=>$start,'end'=>$end]))throw HttpException::conflict('Vehicle or driver has an overlapping allocation.');$this->db->execute('INSERT INTO fleet_trips(company_id,fleet_id,employee_id,starts_at,ends_at,purpose) VALUES(:company,:fleet,:employee,:start,:end,:purpose)',['company'=>$this->company(),'fleet'=>$id,'employee'=>$e['employee_id'],'start'=>$start,'end'=>$end,'purpose'=>$this->text($input['purpose']??null,500)]);return $this->created('fleet_trip');});}
    public function tripAction(string $id,string $action,array $input,bool $self=false):array {return $this->atomic(function()use($id,$action,$input,$self){$this->fields($input,['expected_revision','odometer_km','checks']);$t=$this->row('fleet_trips','trip_id',$id);if($self&&(string)$t['employee_id']!==$this->employee())throw HttpException::notFound();$v=$self?$this->row('fleet_vehicles','fleet_id',$t['fleet_id']):$this->vehicle((string)$t['fleet_id']);$this->access->requireSite($v['site_id']);if($this->number($input['expected_revision']??null)!==(int)$t['revision'])throw HttpException::conflict('Trip changed.');$odo=$this->number($input['odometer_km']??null,(int)$v['odometer_km'],10000000);
        if($action==='start'&&$t['state']==='ALLOCATED'){if($this->row('employees','employee_id',$t['employee_id'])['employment_status']!=='ACTIVE')throw HttpException::forbidden('An inactive employee cannot start a trip.');$checks=$input['checks']??null;$keys=['brakes','tyres','lights','seatbelts','fluid_levels'];if(!is_array($checks)||array_diff($keys,array_keys($checks))||array_diff(array_keys($checks),$keys))throw HttpException::unprocessable('Complete all five pre-trip checks.');foreach($checks as$value)if(!is_bool($value))throw HttpException::unprocessable('Pre-trip checks must be yes/no.');if(gmdate('Y-m-d H:i:s')<$t['starts_at']||gmdate('Y-m-d H:i:s')>$t['ends_at']||$v['state']!=='ACTIVE'||$this->due($v)||$this->db->fetch("SELECT trip_id FROM fleet_trips WHERE company_id=:company AND fleet_id=:fleet AND state='IN_PROGRESS'",['company'=>$this->company(),'fleet'=>$v['fleet_id']]))throw HttpException::conflict('Trip is outside its window, already in use, grounded or due for service.');$state=in_array(false,$checks,true)?'CHECK_FAILED':'IN_PROGRESS';$this->db->execute('UPDATE fleet_trips SET state=:state,revision=revision+1,inspection_json=:checks,start_odometer=:odo WHERE company_id=:company AND trip_id=:id',['state'=>$state,'checks'=>json_encode($checks,JSON_THROW_ON_ERROR),'odo'=>$odo,'company'=>$this->company(),'id'=>$id]);if($state==='CHECK_FAILED')$this->db->execute("UPDATE fleet_vehicles SET state='GROUNDED' WHERE company_id=:company AND fleet_id=:id",['company'=>$this->company(),'id'=>$v['fleet_id']]);}
        elseif($action==='finish'&&$t['state']==='IN_PROGRESS'){$state='COMPLETED';$this->db->execute("UPDATE fleet_trips SET state='COMPLETED',revision=revision+1,end_odometer=:odo,completed_at=:now WHERE company_id=:company AND trip_id=:id",['odo'=>$odo,'now'=>gmdate('Y-m-d H:i:s'),'company'=>$this->company(),'id'=>$id]);}elseif($action==='cancel'&&$t['state']==='ALLOCATED'){$state='CANCELLED';$this->db->execute("UPDATE fleet_trips SET state='CANCELLED',revision=revision+1 WHERE company_id=:company AND trip_id=:id",['company'=>$this->company(),'id'=>$id]);}else throw HttpException::conflict('This trip action is unavailable.');if($action!=='cancel')$this->db->execute('UPDATE fleet_vehicles SET odometer_km=:odo,revision=revision+1 WHERE company_id=:company AND fleet_id=:id',['odo'=>$odo,'company'=>$this->company(),'id'=>$v['fleet_id']]);$this->audit->record('fleet_trip',$action,$id);return ['state'=>$state];});}
    public function fuel(string $id,array $input):array {return $this->atomic(function()use($id,$input){$this->fields($input,['odometer_km','litres_milli','cost_minor','currency','receipt_reference']);$v=$this->vehicle($id);$odo=$this->number($input['odometer_km']??null,(int)$v['odometer_km'],10000000);$currency=$input['currency']??null;if(!in_array($currency,['ZAR','USD','EUR','GBP','NAD','BWP'],true))throw HttpException::unprocessable('Choose a supported currency.');$this->db->execute('INSERT INTO fleet_fuel(company_id,fleet_id,odometer_km,litres_milli,cost_minor,currency,receipt_reference,recorded_by_user_id,recorded_at) VALUES(:company,:fleet,:odo,:litres,:cost,:currency,:receipt,:actor,:now)',['company'=>$this->company(),'fleet'=>$id,'odo'=>$odo,'litres'=>$this->number($input['litres_milli']??null,1,5000000),'cost'=>$this->number($input['cost_minor']??null,0,1000000000),'currency'=>$currency,'receipt'=>$this->text($input['receipt_reference']??null,300),'actor'=>$this->actor(),'now'=>gmdate('Y-m-d H:i:s')]);$result=$this->created('fleet_fuel');$this->db->execute('UPDATE fleet_vehicles SET odometer_km=:odo,revision=revision+1 WHERE company_id=:company AND fleet_id=:id',['odo'=>$odo,'company'=>$this->company(),'id'=>$id]);return $result;});}
    public function service(string $id,array $input):array {return $this->atomic(function()use($id,$input){$this->fields($input,['odometer_km','next_service_km','next_service_on','evidence_reference']);$v=$this->vehicle($id);if($this->db->fetch("SELECT trip_id FROM fleet_trips WHERE company_id=:company AND fleet_id=:fleet AND state='IN_PROGRESS'",['company'=>$this->company(),'fleet'=>$id]))throw HttpException::conflict('Finish the active trip before recording service.');$odo=$this->number($input['odometer_km']??null,(int)$v['odometer_km'],10000000);$next=$this->number($input['next_service_km']??null,$odo+1,10000001);$date=$this->day($input['next_service_on']??null);if($date<=gmdate('Y-m-d'))throw HttpException::unprocessable('Choose the next future service date.');$this->db->execute('INSERT INTO fleet_services(company_id,fleet_id,evidence_reference,odometer_km,next_service_km,next_service_on,recorded_by_user_id,recorded_at) VALUES(:company,:fleet,:evidence,:odo,:next,:date,:actor,:now)',['company'=>$this->company(),'fleet'=>$id,'evidence'=>$this->text($input['evidence_reference']??null,1000),'odo'=>$odo,'next'=>$next,'date'=>$date,'actor'=>$this->actor(),'now'=>gmdate('Y-m-d H:i:s')]);$result=$this->created('fleet_service');$this->db->execute("UPDATE fleet_vehicles SET odometer_km=:odo,next_service_km=:next,next_service_on=:date,state='ACTIVE',revision=revision+1 WHERE company_id=:company AND fleet_id=:id",['odo'=>$odo,'next'=>$next,'date'=>$date,'company'=>$this->company(),'id'=>$id]);return $result;});}
}
